    /// <summary>
    /// The configuration that controls how Amazon AppFlow places data in the destination connector. (structure) Contains information about the configuration of destination con- nectors present in the flow. connectorType -&gt; (string) [required] The type of connector, such as Salesforce, Amplitude, and so on. Possible values: o Salesforce o Singular o Slack o Redshift o S3 o Marketo o Googleanalytics o Zendesk o Servicenow o Datadog o Trendmicro o Snowflake o Dynatrace o Infornexus o Amplitude o Veeva o EventBridge o LookoutMetrics o Upsolver o Honeycode o CustomerProfiles o SAPOData o CustomConnector o Pardot apiVersion -&gt; (string) The API version that the destination connector uses. Constraints: o max: 256 o pattern: \S+ connectorProfileName -&gt; (string) The name of the connector profile. This name must be unique for each connector profile in the Amazon Web Services ac- count. Constraints: o max: 256 o pattern: [\w/!@#+=.-]+ destinationConnectorProperties -&gt; (structure) [required] This stores the information that is required to query a par- ticular connector. Redshift -&gt; (structure) The properties required to query Amazon Redshift. object -&gt; (string) [required] The object specified in the Amazon Redshift flow des- tination. Constraints: o max: 512 o pattern: \S+ intermediateBucketName -&gt; (string) [required] The intermediate bucket that Amazon AppFlow uses when moving data into Amazon Redshift. Constraints: o min: 3 o max: 63 o pattern: \S+ bucketPrefix -&gt; (string) The object key for the bucket in which Amazon AppFlow places the destination files. Constraints: o max: 512 o pattern: .* errorHandlingConfig -&gt; (structure) The settings that determine how Amazon AppFlow handles an error when placing data in the Amazon Redshift des- tination. For example, this setting would determine if the flow should fail after one insertion error, or continue and attempt to insert every record regardless of the initial failure. ErrorHandlingConfig is a part of the destination connector details. failOnFirstDestinationError -&gt; (boolean) Specifies if the flow should fail after the first instance of a failure when attempting to place data in the destination. bucketPrefix -&gt; (string) Specifies the Amazon S3 bucket prefix. Constraints: o max: 512 o pattern: .* bucketName -&gt; (string) Specifies the name of the Amazon S3 bucket. Constraints: o min: 3 o max: 63 o pattern: \S+ S3 -&gt; (structure) The properties required to query Amazon S3. bucketName -&gt; (string) [required] The Amazon S3 bucket name in which Amazon AppFlow places the transferred data. Constraints: o min: 3 o max: 63 o pattern: \S+ bucketPrefix -&gt; (string) The object key for the destination bucket in which Amazon AppFlow places the files. Constraints: o max: 512 o pattern: .* s3OutputFormatConfig -&gt; (structure) The configuration that determines how Amazon AppFlow should format the flow output data when Amazon S3 is used as the destination. fileType -&gt; (string) Indicates the file type that Amazon AppFlow places in the Amazon S3 bucket. Possible values: o CSV o JSON o PARQUET prefixConfig -&gt; (structure) Determines the prefix that Amazon AppFlow applies to the folder name in the Amazon S3 bucket. You can name folders according to the flow frequency and date. prefixType -&gt; (string) Determines the format of the prefix, and whether it applies to the file name, file path, or both. Possible values: o FILENAME o PATH o PATH_AND_FILENAME prefixFormat -&gt; (string) Determines the level of granularity for the date and time that's included in the prefix. Possible values: o YEAR o MONTH o DAY o HOUR o MINUTE pathPrefixHierarchy -&gt; (list) Specifies whether the destination file path in- cludes either or both of the following ele- ments: EXECUTION_ID The ID that Amazon AppFlow assigns to the flow run. SCHEMA_VERSION The version number of your data schema. Amazon AppFlow assigns this version number. The ver- sion number increases by one when you change any of the following settings in your flow con- figuration: o Source-to-destination field mappings o Field data types o Partition keys (string) Possible values: o EXECUTION_ID o SCHEMA_VERSION aggregationConfig -&gt; (structure) The aggregation settings that you can use to cus- tomize the output format of your flow data. aggregationType -&gt; (string) Specifies whether Amazon AppFlow aggregates the flow records into a single file, or leave them unaggregated. Possible values: o None o SingleFile targetFileSize -&gt; (long) The desired file size, in MB, for each output file that Amazon AppFlow writes to the flow destination. For each file, Amazon AppFlow at- tempts to achieve the size that you specify. The actual file sizes might differ from this target based on the number and size of the records that each file contains. preserveSourceDataTyping -&gt; (boolean) If your file output format is Parquet, use this parameter to set whether Amazon AppFlow preserves the data types in your source data when it writes the output to Amazon S3. o true : Amazon AppFlow preserves the data types when it writes to Amazon S3. For example, an in- teger or 1 in your source data is still an inte- ger in your output. o false : Amazon AppFlow converts all of the source data into strings when it writes to Ama- zon S3. For example, an integer of 1 in your source data becomes the string "1" in the out- put. Salesforce -&gt; (structure) The properties required to query Salesforce. object -&gt; (string) [required] The object specified in the Salesforce flow destina- tion. Constraints: o max: 512 o pattern: \S+ idFieldNames -&gt; (list) The name of the field that Amazon AppFlow uses as an ID when performing a write operation such as update or delete. Constraints: o min: 0 (string) Constraints: o max: 128 o pattern: \S+ errorHandlingConfig -&gt; (structure) The settings that determine how Amazon AppFlow handles an error when placing data in the Salesforce destina- tion. For example, this setting would determine if the flow should fail after one insertion error, or con- tinue and attempt to insert every record regardless of the initial failure. ErrorHandlingConfig is a part of the destination connector details. failOnFirstDestinationError -&gt; (boolean) Specifies if the flow should fail after the first instance of a failure when attempting to place data in the destination. bucketPrefix -&gt; (string) Specifies the Amazon S3 bucket prefix. Constraints: o max: 512 o pattern: .* bucketName -&gt; (string) Specifies the name of the Amazon S3 bucket. Constraints: o min: 3 o max: 63 o pattern: \S+ writeOperationType -&gt; (string) This specifies the type of write operation to be per- formed in Salesforce. When the value is UPSERT , then idFieldNames is required. Possible values: o INSERT o UPSERT o UPDATE o DELETE dataTransferApi -&gt; (string) Specifies which Salesforce API is used by Amazon AppFlow when your flow transfers data to Salesforce. AUTOMATIC The default. Amazon AppFlow selects which API to use based on the number of records that your flow trans- fers to Salesforce. If your flow transfers fewer than 1,000 records, Amazon AppFlow uses Salesforce REST API. If your flow transfers 1,000 records or more, Amazon AppFlow uses Salesforce Bulk API 2.0. Each of these Salesforce APIs structures data differ- ently. If Amazon AppFlow selects the API automati- cally, be aware that, for recurring flows, the data output might vary from one flow run to the next. For example, if a flow runs daily, it might use REST API on one day to transfer 900 records, and it might use Bulk API 2.0 on the next day to transfer 1,100 records. For each of these flow runs, the respective Salesforce API formats the data differently. Some of the differences include how dates are formatted and null values are represented. Also, Bulk API 2.0 doesn't transfer Salesforce compound fields. By choosing this option, you optimize flow performance for both small and large data transfers, but the tradeoff is inconsistent formatting in the output. BULKV2 Amazon AppFlow uses only Salesforce Bulk API 2.0. This API runs asynchronous data transfers, and it's optimal for large sets of data. By choosing this option, you ensure that your flow writes consistent output, but you optimize performance only for large data trans- fers. Note that Bulk API 2.0 does not transfer Salesforce compound fields. REST_SYNC Amazon AppFlow uses only Salesforce REST API. By choosing this option, you ensure that your flow writes consistent output, but you decrease performance for large data transfers that are better suited for Bulk API 2.0. In some cases, if your flow attempts to transfer a vary large set of data, it might fail with a timed out error. Possible values: o AUTOMATIC o BULKV2 o REST_SYNC Snowflake -&gt; (structure) The properties required to query Snowflake. object -&gt; (string) [required] The object specified in the Snowflake flow destina- tion. Constraints: o max: 512 o pattern: \S+ intermediateBucketName -&gt; (string) [required] The intermediate bucket that Amazon AppFlow uses when moving data into Snowflake. Constraints: o min: 3 o max: 63 o pattern: \S+ bucketPrefix -&gt; (string) The object key for the destination bucket in which Amazon AppFlow places the files. Constraints: o max: 512 o pattern: .* errorHandlingConfig -&gt; (structure) The settings that determine how Amazon AppFlow handles an error when placing data in the Snowflake destina- tion. For example, this setting would determine if the flow should fail after one insertion error, or con- tinue and attempt to insert every record regardless of the initial failure. ErrorHandlingConfig is a part of the destination connector details. failOnFirstDestinationError -&gt; (boolean) Specifies if the flow should fail after the first instance of a failure when attempting to place data in the destination. bucketPrefix -&gt; (string) Specifies the Amazon S3 bucket prefix. Constraints: o max: 512 o pattern: .* bucketName -&gt; (string) Specifies the name of the Amazon S3 bucket. Constraints: o min: 3 o max: 63 o pattern: \S+ EventBridge -&gt; (structure) The properties required to query Amazon EventBridge. object -&gt; (string) [required] The object specified in the Amazon EventBridge flow destination. Constraints: o max: 512 o pattern: \S+ errorHandlingConfig -&gt; (structure) The settings that determine how Amazon AppFlow handles an error when placing data in the destination. For ex- ample, this setting would determine if the flow should fail after one insertion error, or continue and at- tempt to insert every record regardless of the initial failure. ErrorHandlingConfig is a part of the destina- tion connector details. failOnFirstDestinationError -&gt; (boolean) Specifies if the flow should fail after the first instance of a failure when attempting to place data in the destination. bucketPrefix -&gt; (string) Specifies the Amazon S3 bucket prefix. Constraints: o max: 512 o pattern: .* bucketName -&gt; (string) Specifies the name of the Amazon S3 bucket. Constraints: o min: 3 o max: 63 o pattern: \S+ LookoutMetrics -&gt; (structure) The properties required to query Amazon Lookout for Met- rics. Upsolver -&gt; (structure) The properties required to query Upsolver. bucketName -&gt; (string) [required] The Upsolver Amazon S3 bucket name in which Amazon AppFlow places the transferred data. Constraints: o min: 16 o max: 63 o pattern: ^(upsolver-appflow)\S* bucketPrefix -&gt; (string) The object key for the destination Upsolver Amazon S3 bucket in which Amazon AppFlow places the files. Constraints: o max: 512 o pattern: .* s3OutputFormatConfig -&gt; (structure) [required] The configuration that determines how data is format- ted when Upsolver is used as the flow destination. fileType -&gt; (string) Indicates the file type that Amazon AppFlow places in the Upsolver Amazon S3 bucket. Possible values: o CSV o JSON o PARQUET prefixConfig -&gt; (structure) [required] Specifies elements that Amazon AppFlow includes in the file and folder names in the flow destination. prefixType -&gt; (string) Determines the format of the prefix, and whether it applies to the file name, file path, or both. Possible values: o FILENAME o PATH o PATH_AND_FILENAME prefixFormat -&gt; (string) Determines the level of granularity for the date and time that's included in the prefix. Possible values: o YEAR o MONTH o DAY o HOUR o MINUTE pathPrefixHierarchy -&gt; (list) Specifies whether the destination file path in- cludes either or both of the following ele- ments: EXECUTION_ID The ID that Amazon AppFlow assigns to the flow run. SCHEMA_VERSION The version number of your data schema. Amazon AppFlow assigns this version number. The ver- sion number increases by one when you change any of the following settings in your flow con- figuration: o Source-to-destination field mappings o Field data types o Partition keys (string) Possible values: o EXECUTION_ID o SCHEMA_VERSION aggregationConfig -&gt; (structure) The aggregation settings that you can use to cus- tomize the output format of your flow data. aggregationType -&gt; (string) Specifies whether Amazon AppFlow aggregates the flow records into a single file, or leave them unaggregated. Possible values: o None o SingleFile targetFileSize -&gt; (long) The desired file size, in MB, for each output file that Amazon AppFlow writes to the flow destination. For each file, Amazon AppFlow at- tempts to achieve the size that you specify. The actual file sizes might differ from this target based on the number and size of the records that each file contains. Honeycode -&gt; (structure) The properties required to query Amazon Honeycode. object -&gt; (string) [required] The object specified in the Amazon Honeycode flow des- tination. Constraints: o max: 512 o pattern: \S+ errorHandlingConfig -&gt; (structure) The settings that determine how Amazon AppFlow handles an error when placing data in the destination. For ex- ample, this setting would determine if the flow should fail after one insertion error, or continue and at- tempt to insert every record regardless of the initial failure. ErrorHandlingConfig is a part of the destina- tion connector details. failOnFirstDestinationError -&gt; (boolean) Specifies if the flow should fail after the first instance of a failure when attempting to place data in the destination. bucketPrefix -&gt; (string) Specifies the Amazon S3 bucket prefix. Constraints: o max: 512 o pattern: .* bucketName -&gt; (string) Specifies the name of the Amazon S3 bucket. Constraints: o min: 3 o max: 63 o pattern: \S+ CustomerProfiles -&gt; (structure) The properties required to query Connect Customer Cus- tomer Profiles. domainName -&gt; (string) [required] The unique name of the Connect Customer Customer Pro- files domain. Constraints: o max: 64 o pattern: \S+ objectTypeName -&gt; (string) The object specified in the Connect Customer Customer Profiles flow destination. Constraints: o max: 255 o pattern: \S+ Zendesk -&gt; (structure) The properties required to query Zendesk. object -&gt; (string) [required] The object specified in the Zendesk flow destination. Constraints: o max: 512 o pattern: \S+ idFieldNames -&gt; (list) A list of field names that can be used as an ID field when performing a write operation. Constraints: o min: 0 (string) Constraints: o max: 128 o pattern: \S+ errorHandlingConfig -&gt; (structure) The settings that determine how Amazon AppFlow handles an error when placing data in the destination. For ex- ample, this setting would determine if the flow should fail after one insertion error, or continue and at- tempt to insert every record regardless of the initial failure. ErrorHandlingConfig is a part of the destina- tion connector details. failOnFirstDestinationError -&gt; (boolean) Specifies if the flow should fail after the first instance of a failure when attempting to place data in the destination. bucketPrefix -&gt; (string) Specifies the Amazon S3 bucket prefix. Constraints: o max: 512 o pattern: .* bucketName -&gt; (string) Specifies the name of the Amazon S3 bucket. Constraints: o min: 3 o max: 63 o pattern: \S+ writeOperationType -&gt; (string) The possible write operations in the destination con- nector. When this value is not provided, this defaults to the INSERT operation. Possible values: o INSERT o UPSERT o UPDATE o DELETE Marketo -&gt; (structure) The properties required to query Marketo. object -&gt; (string) [required] The object specified in the Marketo flow destination. Constraints: o max: 512 o pattern: \S+ errorHandlingConfig -&gt; (structure) The settings that determine how Amazon AppFlow handles an error when placing data in the destination. For ex- ample, this setting would determine if the flow should fail after one insertion error, or continue and at- tempt to insert every record regardless of the initial failure. ErrorHandlingConfig is a part of the destina- tion connector details. failOnFirstDestinationError -&gt; (boolean) Specifies if the flow should fail after the first instance of a failure when attempting to place data in the destination. bucketPrefix -&gt; (string) Specifies the Amazon S3 bucket prefix. Constraints: o max: 512 o pattern: .* bucketName -&gt; (string) Specifies the name of the Amazon S3 bucket. Constraints: o min: 3 o max: 63 o pattern: \S+ CustomConnector -&gt; (structure) The properties that are required to query the custom Con- nector. entityName -&gt; (string) [required] The entity specified in the custom connector as a des- tination in the flow. Constraints: o max: 1024 o pattern: \S+ errorHandlingConfig -&gt; (structure) The settings that determine how Amazon AppFlow handles an error when placing data in the custom connector as destination. failOnFirstDestinationError -&gt; (boolean) Specifies if the flow should fail after the first instance of a failure when attempting to place data in the destination. bucketPrefix -&gt; (string) Specifies the Amazon S3 bucket prefix. Constraints: o max: 512 o pattern: .* bucketName -&gt; (string) Specifies the name of the Amazon S3 bucket. Constraints: o min: 3 o max: 63 o pattern: \S+ writeOperationType -&gt; (string) Specifies the type of write operation to be performed in the custom connector when it's used as destination. Possible values: o INSERT o UPSERT o UPDATE o DELETE idFieldNames -&gt; (list) The name of the field that Amazon AppFlow uses as an ID when performing a write operation such as update, delete, or upsert. Constraints: o min: 0 (string) Constraints: o max: 128 o pattern: \S+ customProperties -&gt; (map) The custom properties that are specific to the connec- tor when it's used as a destination in the flow. Constraints: o min: 0 o max: 50 key -&gt; (string) Constraints: o min: 1 o max: 128 o pattern: [\w]+ value -&gt; (string) Constraints: o max: 2048 o pattern: \S+ SAPOData -&gt; (structure) The properties required to query SAPOData. objectPath -&gt; (string) [required] The object path specified in the SAPOData flow desti- nation. Constraints: o max: 512 o pattern: \S+ successResponseHandlingConfig -&gt; (structure) Determines how Amazon AppFlow handles the success re- sponse that it gets from the connector after placing data. For example, this setting would determine where to write the response from a destination connector upon a successful insert operation. bucketPrefix -&gt; (string) The Amazon S3 bucket prefix. Constraints: o max: 512 o pattern: .* bucketName -&gt; (string) The name of the Amazon S3 bucket. Constraints: o min: 3 o max: 63 o pattern: \S+ idFieldNames -&gt; (list) A list of field names that can be used as an ID field when performing a write operation. Constraints: o min: 0 (string) Constraints: o max: 128 o pattern: \S+ errorHandlingConfig -&gt; (structure) The settings that determine how Amazon AppFlow handles an error when placing data in the destination. For ex- ample, this setting would determine if the flow should fail after one insertion error, or continue and at- tempt to insert every record regardless of the initial failure. ErrorHandlingConfig is a part of the destina- tion connector details. failOnFirstDestinationError -&gt; (boolean) Specifies if the flow should fail after the first instance of a failure when attempting to place data in the destination. bucketPrefix -&gt; (string) Specifies the Amazon S3 bucket prefix. Constraints: o max: 512 o pattern: .* bucketName -&gt; (string) Specifies the name of the Amazon S3 bucket. Constraints: o min: 3 o max: 63 o pattern: \S+ writeOperationType -&gt; (string) The possible write operations in the destination con- nector. When this value is not provided, this defaults to the INSERT operation. Possible values: o INSERT o UPSERT o UPDATE o DELETE JSON Syntax: [ { "connectorType": "Salesforce"|"Singular"|"Slack"|"Redshift"|"S3"|"Marketo"|"Googleanalytics"|"Zendesk"|"Servicenow"|"Datadog"|"Trendmicro"|"Snowflake"|"Dynatrace"|"Infornexus"|"Amplitude"|"Veeva"|"EventBridge"|"LookoutMetrics"|"Upsolver"|"Honeycode"|"CustomerProfiles"|"SAPOData"|"CustomConnector"|"Pardot", "apiVersion": "string", "connectorProfileName": "string", "destinationConnectorProperties": { "Redshift": { "object": "string", "intermediateBucketName": "string", "bucketPrefix": "string", "errorHandlingConfig": { "failOnFirstDestinationError": true|false, "bucketPrefix": "string", "bucketName": "string" } }, "S3": { "bucketName": "string", "bucketPrefix": "string", "s3OutputFormatConfig": { "fileType": "CSV"|"JSON"|"PARQUET", "prefixConfig": { "prefixType": "FILENAME"|"PATH"|"PATH_AND_FILENAME", "prefixFormat": "YEAR"|"MONTH"|"DAY"|"HOUR"|"MINUTE", "pathPrefixHierarchy": ["EXECUTION_ID"|"SCHEMA_VERSION", ...] }, "aggregationConfig": { "aggregationType": "None"|"SingleFile", "targetFileSize": long }, "preserveSourceDataTyping": true|false } }, "Salesforce": { "object": "string", "idFieldNames": ["string", ...], "errorHandlingConfig": { "failOnFirstDestinationError": true|false, "bucketPrefix": "string", "bucketName": "string" }, "writeOperationType": "INSERT"|"UPSERT"|"UPDATE"|"DELETE", "dataTransferApi": "AUTOMATIC"|"BULKV2"|"REST_SYNC" }, "Snowflake": { "object": "string", "intermediateBucketName": "string", "bucketPrefix": "string", "errorHandlingConfig": { "failOnFirstDestinationError": true|false, "bucketPrefix": "string", "bucketName": "string" } }, "EventBridge": { "object": "string", "errorHandlingConfig": { "failOnFirstDestinationError": true|false, "bucketPrefix": "string", "bucketName": "string" } }, "LookoutMetrics": { }, "Upsolver": { "bucketName": "string", "bucketPrefix": "string", "s3OutputFormatConfig": { "fileType": "CSV"|"JSON"|"PARQUET", "prefixConfig": { "prefixType": "FILENAME"|"PATH"|"PATH_AND_FILENAME", "prefixFormat": "YEAR"|"MONTH"|"DAY"|"HOUR"|"MINUTE", "pathPrefixHierarchy": ["EXECUTION_ID"|"SCHEMA_VERSION", ...] }, "aggregationConfig": { "aggregationType": "None"|"SingleFile", "targetFileSize": long } } }, "Honeycode": { "object": "string", "errorHandlingConfig": { "failOnFirstDestinationError": true|false, "bucketPrefix": "string", "bucketName": "string" } }, "CustomerProfiles": { "domainName": "string", "objectTypeName": "string" }, "Zendesk": { "object": "string", "idFieldNames": ["string", ...], "errorHandlingConfig": { "failOnFirstDestinationError": true|false, "bucketPrefix": "string", "bucketName": "string" }, "writeOperationType": "INSERT"|"UPSERT"|"UPDATE"|"DELETE" }, "Marketo": { "object": "string", "errorHandlingConfig": { "failOnFirstDestinationError": true|false, "bucketPrefix": "string", "bucketName": "string" } }, "CustomConnector": { "entityName": "string", "errorHandlingConfig": { "failOnFirstDestinationError": true|false, "bucketPrefix": "string", "bucketName": "string" }, "writeOperationType": "INSERT"|"UPSERT"|"UPDATE"|"DELETE", "idFieldNames": ["string", ...], "customProperties": {"string": "string" ...} }, "SAPOData": { "objectPath": "string", "successResponseHandlingConfig": { "bucketPrefix": "string", "bucketName": "string" }, "idFieldNames": ["string", ...], "errorHandlingConfig": { "failOnFirstDestinationError": true|false, "bucketPrefix": "string", "bucketName": "string" }, "writeOperationType": "INSERT"|"UPSERT"|"UPDATE"|"DELETE" } } } ... ]
